// MakeNumEqual builds the canonical (shared) NumEqual term.
func MakeNumEqual() NumericConstraintType {
	hashes := []uint32{}
	proto := &NumEqualNumericConstraintType{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("NumEqual"), hashes)}
	return factory.Build(proto).(*NumEqualNumericConstraintType)
}

// ConstraintList is the Go interface backing the Gom sort ConstraintList.
type ConstraintList interface {
	sharedobjects.Term
	isConstraintList()
}

// ConcConstraintConstraintList is the term type for the alternative `concConstraint(...)` of sort ConstraintList.
type ConcConstraintConstraintList struct {
	Slots []Constraint
	hash  uint32
}

func (*ConcConstraintConstraintList) isConstraintList() {}

func (t *ConcConstraintConstraintList) Hash() uint32 { return t.hash }

func (t *ConcConstraintConstraintList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcConstraintConstraintList)
	if !ok {
		return false
	}
	if len(t.Slots) != len(o.Slots) {
		return false
	}
	for i := range t.Slots {
		if t.Slots[i] != o.Slots[i] {
			return false
		}
	}
	return true
}

func (t *ConcConstraintConstraintList) Duplicate() sharedobjects.Term {
	cp := append([]Constraint(nil), t.Slots...)
	return &ConcConstraintConstraintList{Slots: cp, hash: t.hash}
}

func (t *ConcConstraintConstraintList) String() string {
	parts := make([]string, len(t.Slots))
	for i, v := range t.Slots {
		parts[i] = fmt.Sprintf("%v", v)
	}
	return "concConstraint" + "(" + strings.Join(parts, ",") + ")"
}

// MakeConcConstraint builds the canonical (shared) concConstraint term.
func MakeConcConstraint(args ...Constraint) ConstraintList {
	hashes := make([]uint32, 0, len(args))
	for _, a := range args {
		hashes = append(hashes, a.Hash())
	}
	proto := &ConcConstraintConstraintList{Slots: args, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("concConstraint"), hashes)}
	return factory.Build(proto).(*ConcConstraintConstraintList)
}
